((e.aggregate_type='operations_exception' AND e.event_type IN ('operations.exception.open','operations.exception.acknowledge','operations.exception.start','operations.exception.resolve','operations.exception.approve','operations.exception.reject','operations.exception.close','operations.exception.reopen','operations.exception.assign','operations.exception.prioritize','operations.exception.escalate','operations.exception.cancel') AND EXISTS(SELECT 1 FROM operations_exceptions s WHERE s.id=e.aggregate_id AND s.source_kind='field_service_order' AND s.company_id=e.payload_json::jsonb->>'companyId' AND s.version>=e.aggregate_version)) OR (e.aggregate_type='operations_policy' AND e.event_type IN ('operations.policy.draft','operations.policy.publish','operations.policy.reject','operations.policy.retire') AND EXISTS(SELECT 1 FROM operations_queue_policies s WHERE s.id=e.aggregate_id AND jsonb_typeof(s.source_kinds_json::jsonb)='array' AND s.source_kinds_json::jsonb<>'[]'::jsonb AND s.source_kinds_json::jsonb <@ '["field_service_order"]'::jsonb AND s.company_id=e.payload_json::jsonb->>'companyId' AND s.version>=e.aggregate_version)))
